function countTriples(n) {
  let count = 0;

  for (let a = 1; a <= n; a++) {
    for (let b = 1; b <= n; b++) {
      const sumOfSquares = a * a + b * b;
      const c = Math.round(Math.sqrt(sumOfSquares));
      if (c <= n && c * c === sumOfSquares) {
        count++;
      }
    }
  }
  return count;
}

