function countTriples(n) {
  // Try every c, and for each a look up whether c² - a² is a perfect square b² in range.
  const squares = new Set();
  for (let v = 1; v <= n; v++) squares.add(v * v);
  let total = 0;
  for (let c = 1; c <= n; c++) {
    for (let a = 1; a < c; a++) {
      if (squares.has(c * c - a * a)) total++;
    }
  }
  return total;
}

